// ============================================================
// MineraAI → ComfyUI RunPod — FÁBRICA DE VÍDEOS
// Recebe roteiro completo do Estúdio IA ou Curadoria e monta workflow
// ============================================================
const job = $input.first().json.body || $input.first().json;

const tipo = job.tipo || 'video';
const product = job.product || 'produto';
const style = job.style || 'ugc';
const duration = job.duration || 6;
const roteiro = job.roteiro || {};
const extraPrompts = job.prompts || [];

// Estilos mapeados para prefixos de prompt
const STYLE_PREFIX = {
  ugc: 'foto amadora estilo UGC, luz natural, mão tremendo levemente, iPhone photo, casa real, autêntico, ', 
  dark: 'dark aesthetic, moody lighting, cinematic shadows, misterioso, suspense, ', 
  cinematic: 'cinematic lighting, 8k, ultra detailed, professional color grading, dramatic, ', 
  produto: 'product photography, studio lighting, clean background, commercial, high detail, ',
  anime: 'anime style, studio ghibli, vibrant colors, detailed illustration, '
};
const prefix = STYLE_PREFIX[style] || STYLE_PREFIX.ugc;

// Monta prompt principal
let promptBase = job.prompt || '';
if (roteiro.hook) promptBase = `${roteiro.hook}. ${promptBase}`;
if (roteiro.narracao) promptBase = `${promptBase}. Narração: ${roteiro.narracao.slice(0,200)}`;

const promptPositivo = [
  prefix,
  `Produto: ${product}`,
  promptBase,
  `Estilo: ${style}, duração ${duration}s`,
  'vertical 9:16, alta qualidade, iluminação cinematográfica, movimento suave',
  extraPrompts.join(', ')
].filter(Boolean).join(', ');

// Se tem cenas no roteiro, extrai prompts por cena
let cenas = roteiro.cenas || [];
if (!cenas.length && roteiro.cenas === undefined) {
  // fallback: cria cenas genéricas a partir do prompt
  cenas = [
    { nome: 'GANCHO', prompt: `${prefix} close-up reação surpresa, ${product} desfocado fundo, hook visual forte, 9:16`, duracao: '2s' },
    { nome: 'DEMO', prompt: `${prefix} ${product} em uso real, demonstração, cozinha real, ${promptBase}, 9:16`, duracao: '3s' },
    { nome: 'CTA', prompt: `${prefix} ${product} com CTA visual, texto 'LINK NA BIO', produto destaque, 9:16`, duracao: '1s' }
  ];
}

// Workflow ComfyUI AnimateDiff para vídeo — API Format
// >>> SUBSTITUA ckpt_name e motion model pelos seus no RunPod <<<
const seed = Math.floor(Math.random()*1e15);
const workflow = {
  '1': { class_type: 'CheckpointLoaderSimple', inputs: { ckpt_name: 'realisticVisionV60B1_v51HyperVAE.safetensors' } },
  '2': { class_type: 'ADE_LoadAnimateDiffModel', inputs: { model_name: 'mm_sd_v15_v2.ckpt' } },
  '3': { class_type: 'ADE_AnimateDiffLoaderWithContext', inputs: { model: ['1',0], motion_model: ['2',0], beta_schedule: 'sqrt_linear (AnimateDiff)', context_length: 16, context_stride: 1, context_overlap: 4, context_schedule: 'uniform', closed_loop: false } },
  '4': { class_type: 'EmptyLatentImage', inputs: { width: 512, height: 768, batch_size: 16 } },
  '6': { class_type: 'CLIPTextEncode', inputs: { text: promptPositivo.slice(0,1500), clip: ['1',1] } },
  '7': { class_type: 'CLIPTextEncode', inputs: { text: "low quality, blurry, texto, marca d'água, baixa qualidade, borrado, deformado, extra fingers, static, no movement, logo", clip: ['1',1] } },
  '8': { class_type: 'KSampler', inputs: { seed, steps: 25, cfg: 7.0, sampler_name: 'dpmpp_2m', scheduler: 'karras', denoise: 1, model: ['3',0], positive: ['6',0], negative: ['7',0], latent_image: ['4',0] } },
  '9': { class_type: 'VAEDecode', inputs: { samples: ['8',0], vae: ['1',2] } },
  '10': { class_type: 'VHS_VideoCombine', inputs: { images: ['9',0], frame_rate: 8, loop_count: 0, filename_prefix: `mineraai/video_${job.job_id}`, format: 'video/h264-mp4', pix_fmt: 'yuv420p', crf: 19, save_metadata: false } }
};

// Para roteiro com múltiplas cenas, poderíamos criar múltiplos KSamplers, mas aqui mantemos 1 vídeo geral
// Opcional: injetar cenas nos prompts extras para referência
const meta = { tipo, product, style, duration, cenas: cenas.map(c => ({ nome: c.nome, prompt: (c.prompt || c.descricao || '').slice(0,200) })), roteiro_hook: roteiro.hook || '' };

return [{ json: { job_id: job.job_id, tipo, callback_url: job.callback_url, token: job.token, product, prompt: promptPositivo, meta, input: { workflow } } }];

// Extrai URLs de vídeo e imagens do output RunPod
const r = $input.first().json;
const out = r.output || {};
let video_url = '';
let images = [];

// RunPod worker-comfyui pode retornar de várias formas
if (typeof out === 'string') video_url = out;
else if (Array.isArray(out)) {
  // array de strings ou objetos
  for (const item of out) {
    if (typeof item === 'string' && (item.includes('.mp4') || item.includes('video'))) video_url = item;
    else if (typeof item === 'object' && item.url) {
      if (item.url.includes('.mp4')) video_url = item.url;
      else images.push({ url: item.url, prompt: '', cena: '' });
    }
  }
} else if (out && typeof out === 'object') {
  video_url = out.video_url || out.video || out.url || '';
  // tenta extrair images
  if (out.images && Array.isArray(out.images)) {
    images = out.images.map(img => typeof img === 'string' ? { url: img } : { url: img.url || img.filename || '', prompt: img.prompt || '' });
  }
  if (out.message && typeof out.message === 'string' && out.message.includes('http')) {
    // fallback: procura URL na mensagem
    const m = out.message.match(/https?:\/\/[^\s]+\.mp4[^\s]*/);
    if (m) video_url = m[0];
  }
  // Se não tem video_url mas tem filename, constrói URL via R2/S3 base
  if (!video_url && out.filename) video_url = out.filename;
}

const job = $('Montar Workflow ComfyUI Vídeo').first().json;
return [{ json: { job_id: job.job_id, callback_url: job.callback_url, token: job.token, video_url, images, meta: job.meta, cost_usd: r.cost || r.executionTime ? (r.executionTime/1000*0.0005) : null } }];
